// iostream gives us std::cout, the console output.
#include <iostream>

// Every C++ program starts running in main().
int main() {
    std::cout << "Hello, world!" << std::endl;

    // << chains several pieces into one line.
    std::cout << "Welcome to " << "C++" << " in DMarlon Studio" << '\n';

    // Numbers are printed just like text.
    std::cout << "This course has " << 20 << " lessons." << '\n';
    std::cout << "2 + 3 = " << 2 + 3 << '\n';

    // \n starts a new line inside the text; \t inserts a tab.
    std::cout << "Line one\nLine two\n";
    std::cout << "Name:\tAda\n";

    // Returning 0 tells the system that everything went well.
    return 0;
}

#include <iostream>
#include <string>

int main() {
    // Each variable has a type, a name and (always, better) a value.
    int age = 34;
    double height = 1.78;
    char grade = 'A';
    bool member = true;
    std::string name = "Lucia";

    std::cout << name << " is " << age << " years old\n";
    std::cout << "Height: " << height << " m, grade " << grade << '\n';
    std::cout << "Member: " << member << '\n';  // a bool prints 1 or 0

    // A variable can change its value, but never its type.
    age = age + 1;
    std::cout << "Next year: " << age << '\n';

    // const: a value that must not change.
    const double vat = 0.21;

    // auto: the compiler deduces the type from the value.
    auto price = 49.90;  // double
    auto units = 3;      // int
    auto total = price * units * (1 + vat);
    std::cout << "Total with VAT: " << total << '\n';

    // sizeof tells how many bytes a type takes in memory.
    std::cout << "int: " << sizeof(int) << " bytes, double: " << sizeof(double) << " bytes\n";
    return 0;
}

#include <cmath>
#include <iostream>

int main() {
    // With two ints, / is integer division and % gives the remainder.
    int cookies = 17, children = 5;
    std::cout << "Each child gets " << cookies / children << " cookies\n";
    std::cout << "Left over: " << cookies % children << '\n';

    // If one side is a double, the result keeps the decimals.
    std::cout << "Exact share: " << cookies / 5.0 << '\n';
    // static_cast converts a value to another type.
    std::cout << "Average: " << static_cast<double>(cookies) / children << '\n';

    int score = 10;  // compound operators: += -= *= /=, and ++
    score += 5;  // 15
    score *= 2;  // 30
    score++;     // 31
    std::cout << "Score: " << score << '\n';

    // <cmath> brings the maths functions.
    double a = 3.0, b = 4.0;
    std::cout << "Hypotenuse: " << std::sqrt(a * a + b * b) << '\n';
    std::cout << "2 to the 10th: " << std::pow(2, 10) << '\n';
    std::cout << "round(7.5): " << std::round(7.5) << ", floor(7.5): " << std::floor(7.5)
              << ", ceil(7.2): " << std::ceil(7.2) << '\n';
    std::cout << "abs(-12.5): " << std::abs(-12.5) << '\n';

    // Area of a pizza 30 cm across.
    const double pi = 3.14159265358979;
    double radius = 15;
    std::cout << "Pizza area: " << pi * std::pow(radius, 2) << " cm2\n";
    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string first = "Grace";
    std::string last = "Hopper";
    // + joins strings; size() counts the characters.
    std::string full = first + " " + last;
    std::cout << full << " has " << full.size() << " characters\n";

    // [] reads one character by position (the first one is 0).
    std::cout << "Initials: " << first[0] << last[0] << '\n';

    // substr(start, length) copies a part; without length, up to the end.
    std::string code = "ES-2024-MAD";
    std::cout << "Country: " << code.substr(0, 2) << ", city: " << code.substr(8) << '\n';

    // find() returns the position, or std::string::npos if it is missing.
    std::cout << "The year starts at position " << code.find("2024") << '\n';
    std::cout << "BCN found? " << (code.find("BCN") != std::string::npos) << '\n';

    // A std::string can grow and be changed in place.
    std::string message = "Order";
    message += " shipped";
    message.replace(0, 5, "Parcel");
    std::cout << message << '\n';

    // Converting between text and numbers.
    int units = std::stoi("12");
    double price = std::stod("2.5");
    std::cout << "Units: " + std::to_string(units) << ", total: " << units * price << '\n';
    return 0;
}

#include <iostream>
